import * as THREE from "three";
import { ExtrudeGeometry } from "three";
import { LayerRenderer } from "./LayerRenderer.js";

export class BuildingsRenderer extends LayerRenderer {
  renderFeature(feature) {
    const geom = feature.geometry;
    const h = feature.properties?.height || 50;
    const meshes = [];

    if (geom.type === "Polygon") {
      const m = this._polygonToMesh(geom.coordinates, h);
      if (m) meshes.push(m);
    } else if (geom.type === "MultiPolygon") {
      for (const poly of geom.coordinates) {
        const m = this._polygonToMesh(poly, h);
        if (m) meshes.push(m);
      }
    }

    return meshes;
  }

  _ensureClosed(ring) {
    if (!ring || ring.length < 1) return ring;
    const a = ring[0];
    const b = ring[ring.length - 1];
    if (a[0] !== b[0] || a[1] !== b[1]) return [...ring, a];
    return ring;
  }

  _polygonToMesh(polygonCoords, height) {
    if (!Array.isArray(polygonCoords) || polygonCoords.length < 1) return null;
    const outer = this._ensureClosed(polygonCoords[0]);
    if (!outer || outer.length < 3) return null;

    const shape = new THREE.Shape();
    for (let i = 0; i < outer.length; i++) {
      const [lon, lat] = outer[i];
      const [x, z] = this.toLocal(lon, lat);
      if (i === 0) shape.moveTo(x, z);
      else shape.lineTo(x, z);
    }

    for (let h = 1; h < polygonCoords.length; h++) {
      const holeRing = this._ensureClosed(polygonCoords[h]);
      const pts = holeRing.map(([lon, lat]) => {
        const [x, z] = this.toLocal(lon, lat);
        return new THREE.Vector2(x, z);
      });
      const path = new THREE.Path(pts);
      shape.holes.push(path);
    }

    // Уменьшаем высоту экструзии, если она слишком большая
    const clampedHeight = Math.min(height, 500);

    const extrude = new ExtrudeGeometry(shape, {
      depth: clampedHeight,
      bevelEnabled: false,
    });

    // ВАЖНО: не мержим геометрию с rotateX, а создаём отдельный меш с правильной ориентацией
    extrude.rotateX(-Math.PI / 2);
    extrude.computeVertexNormals();

    const mesh = new THREE.Mesh(
      extrude,
      new THREE.MeshStandardMaterial({
        color: 0xcccccc,
        roughness: 0.8,
        metalness: 0.2,
      })
    );
    mesh.castShadow = true;
    mesh.receiveShadow = true;

    return mesh;
  }
}

export class RoadsRenderer extends LayerRenderer {
  renderFeature(feature) {
    const geom = feature.geometry;
    const props = feature.properties || {};
    const meshes = [];

    if (geom.type === "LineString") {
      const m = this._lineToMesh(geom.coordinates, props);
      if (m) meshes.push(m);
    } else if (geom.type === "MultiLineString") {
      for (const ls of geom.coordinates) {
        const m = this._lineToMesh(ls, props);
        if (m) meshes.push(m);
      }
    }

    return meshes;
  }

  _lineToMesh(coords, props) {
    if (!coords || coords.length < 2) return null;
    const y = 0.12;

    const pts = coords.map(([lon, lat]) => {
      const [x, z] = this.toLocal(lon, lat);
      return new THREE.Vector3(x, y, z);
    });

    const width = this._getRoadWidth(props);
    const geometry = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const uvs = [];

    for (let i = 0; i < pts.length - 1; i++) {
      const p1 = pts[i];
      const p2 = pts[i + 1];

      const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
      const perp = new THREE.Vector3(-dir.z, 0, dir.x).multiplyScalar(
        width / 2
      );

      const v1 = p1.clone().add(perp);
      const v2 = p1.clone().sub(perp);
      const v3 = p2.clone().add(perp);
      const v4 = p2.clone().sub(perp);

      const idx = i * 4;
      positions.push(
        v1.x,
        v1.y,
        v1.z,
        v2.x,
        v2.y,
        v2.z,
        v3.x,
        v3.y,
        v3.z,
        v4.x,
        v4.y,
        v4.z
      );
      const u = i / (pts.length - 1);
      const du = 1 / (pts.length - 1);
      uvs.push(u, 0, u, 1, u + du, 0, u + du, 1);
      indices.push(idx, idx + 1, idx + 2, idx + 1, idx + 3, idx + 2);
    }

    geometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(positions, 3)
    );
    geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();

    const material = new THREE.MeshStandardMaterial({
      color: this._getRoadColor(props),
      roughness: 1.0,
      metalness: 0.0,
      polygonOffset: true,
      polygonOffsetFactor: -3,
      polygonOffsetUnits: -3,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = -Math.PI;
    return mesh;
  }

  _getRoadWidth(props) {
    const type = props.fclass || props.highway || props.type || "unknown";
    const widths = {
      motorway: 15,
      trunk: 12,
      primary: 10,
      secondary: 8,
      tertiary: 6,
      residential: 5,
      service: 3,
      path: 2,
      footway: 1.5,
    };
    return widths[type] || 5;
  }

  _getRoadColor(props) {
    const type = props.fclass || props.highway || props.type || "unknown";
    const colors = {
      motorway: 0xe892a2,
      trunk: 0xf9b29c,
      primary: 0xfcd6a4,
      secondary: 0xf7fabf,
      tertiary: 0xffffff,
      residential: 0xffffff,
      service: 0xffffff,
      path: 0xc5b3a0,
      footway: 0xc5b3a0,
    };
    return colors[type] || 0xdddddd;
  }
}

export class RiversRenderer extends LayerRenderer {
  renderFeature(feature) {
    const geom = feature.geometry;
    const props = feature.properties || {};
    const meshes = [];

    if (geom.type === "Polygon") {
      const m = this._waterPolygonToMesh(geom.coordinates);
      if (m) meshes.push(m);
    } else if (geom.type === "MultiPolygon") {
      for (const poly of geom.coordinates) {
        const m = this._waterPolygonToMesh(poly);
        if (m) meshes.push(m);
      }
    }
    else if (geom.type === "LineString") {
      const m = this._waterLineToMesh(geom.coordinates, props);
      if (m) meshes.push(m);
    } else if (geom.type === "MultiLineString") {
      for (const ls of geom.coordinates) {
        const m = this._waterLineToMesh(ls, props);
        if (m) meshes.push(m);
      }
    }

    return meshes;
  }

  _waterPolygonToMesh(polygonCoords) {
    if (!Array.isArray(polygonCoords) || polygonCoords.length < 1) return null;
    const outer = polygonCoords[0];
    if (!outer || outer.length < 3) return null;

    const shape = new THREE.Shape();
    for (let i = 0; i < outer.length; i++) {
      const [lon, lat] = outer[i];
      const [x, z] = this.toLocal(lon, lat);
      if (i === 0) shape.moveTo(x, z);
      else shape.lineTo(x, z);
    }

    for (let h = 1; h < polygonCoords.length; h++) {
      const holeRing = polygonCoords[h];
      const pts = holeRing.map(([lon, lat]) => {
        const [x, z] = this.toLocal(lon, lat);
        return new THREE.Vector2(x, z);
      });
      const path = new THREE.Path(pts);
      shape.holes.push(path);
    }

    const geometry = new THREE.ShapeGeometry(shape);
    geometry.rotateX(-Math.PI / 2);
    geometry.computeVertexNormals();

    const material = new THREE.MeshStandardMaterial({
      color: 0x4a90e2,
      roughness: 0.1,
      metalness: 0.6,
      transparent: true,
      opacity: 0.85,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.y = 0.05;
    mesh.receiveShadow = true;

    return mesh;
  }

  _waterLineToMesh(coords, props) {
    if (!coords || coords.length < 2) return null;
    const y = 0.05;

    const pts = coords.map(([lon, lat]) => {
      const [x, z] = this.toLocal(lon, lat);
      return new THREE.Vector3(x, y, z);
    });

    const width = this._getWaterWidth(props);
    const geometry = new THREE.BufferGeometry();
    const positions = [];
    const indices = [];
    const uvs = [];

    for (let i = 0; i < pts.length - 1; i++) {
      const p1 = pts[i];
      const p2 = pts[i + 1];

      const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
      const perp = new THREE.Vector3(-dir.z, 0, dir.x).multiplyScalar(
        width / 2
      );

      const v1 = p1.clone().add(perp);
      const v2 = p1.clone().sub(perp);
      const v3 = p2.clone().add(perp);
      const v4 = p2.clone().sub(perp);

      const idx = i * 4;
      positions.push(
        v1.x,
        v1.y,
        v1.z,
        v2.x,
        v2.y,
        v2.z,
        v3.x,
        v3.y,
        v3.z,
        v4.x,
        v4.y,
        v4.z
      );
      const u = i / (pts.length - 1);
      const du = 1 / (pts.length - 1);
      uvs.push(u, 0, u, 1, u + du, 0, u + du, 1);
      indices.push(idx, idx + 1, idx + 2, idx + 1, idx + 3, idx + 2);
    }

    geometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(positions, 3)
    );
    geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();

    const material = new THREE.MeshStandardMaterial({
      color: 0x4a90e2,
      roughness: 0.1,
      metalness: 0.6,
      transparent: true,
      opacity: 0.85,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = -Math.PI;
    mesh.receiveShadow = true;

    return mesh;
  }

  _getWaterWidth(props) {
    const type = props.fclass || props.waterway || props.type || "unknown";
    const widths = {
      river: 25,
      stream: 8,
      canal: 12,
      drain: 5,
      ditch: 3,
    };
    return widths[type] || 15;
  }
}

