import * as THREE from "three";
import proj4 from "proj4";

export class LayerRenderer {
  constructor(centerOffset = [0, 0]) {
    this.centerOffset = centerOffset; // смещение для текущего чанка
    this.wgs84 = "EPSG:4326";
    this.webMercator = "EPSG:3857";
  }

  // Преобразование координат из WGS84 в локальные XYZ относительно centerOffset
  toLocal(lon, lat) {
    const [x0, z0] = proj4(this.wgs84, this.webMercator, [lon, lat]);
    const x = x0 - this.centerOffset[0];
    const z = z0 - this.centerOffset[1];
    return [x, z];
  }

  renderFeature(feature) {
    throw new Error("Not implemented");
  }
}
