"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "./three/ChunkLoader";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { OverlayInfo } from "./OverlayInfo";

export default function ThreeScene({ settings }) {
  const ref = useRef(null);
  const wgs84 = "EPSG:4326";
  const webMercator = "EPSG:3857";

  const [cameraObj, setCameraObj] = useState(null);
  const [loaders, setLoaders] = useState({});
  const [status, setStatus] = useState({
    chunks: 0,
    meshes: 0,
    features: 0,
    lastQueryMs: 0,
  });

  useEffect(() => {
    const container = ref.current;
    if (!container) return;

    const renderer = createRenderer(container);
    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = 60;
    camera.updateProjectionMatrix();
    setCameraObj(camera);

    const controls = createControls(camera, renderer.domElement);

    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "30.5234");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "50.4501");

    const [centerX, centerZ] = proj4(wgs84, webMercator, [startLon, startLat]);

    camera.position.set(0, 800, 800);
    camera.lookAt(0, 0, 0);
    controls.target.set(0, 0, 0);
    controls.update();

    const { scene, cube } = createScene();
    scene.background = new THREE.Color(0xbfd9ff);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
    dirLight.position.set(1000, 2000, 1000);
    scene.add(dirLight);

    const ambLight = new THREE.AmbientLight(0x666666, 0.8);
    scene.add(ambLight);

    const cleanupRaycast = setupRaycast(
      renderer.domElement,
      camera,
      scene,
      controls,
      container
    );

    const waterLoader = new ChunkLoader(scene, {
      url: "http://127.0.0.1:8000/chunk/water",
      centerOffset: [centerX, centerZ],
      layerType: "water",
      onProgress: (meta) => {
        setStatus((s) => ({
          ...s,
          water: meta.rendered || 0,
        }));
      },
    });

    const buildingsLoader = new ChunkLoader(scene, {
      url: "http://127.0.0.1:8000/chunk/buildings",
      centerOffset: [centerX, centerZ],
      layerType: "buildings",
      onProgress: (meta) => {
        setStatus((s) => ({
          ...s,
          buildings: meta.rendered || 0,
          lastQueryMs: meta.queryTimeMs || s.lastQueryMs,
        }));
      },
    });

    const roadsLoader = new ChunkLoader(scene, {
      url: "http://127.0.0.1:8000/chunk/roads",
      centerOffset: [centerX, centerZ],
      layerType: "roads",
      onProgress: (meta) => {
        setStatus((s) => ({
          ...s,
          roads: meta.rendered || 0,
        }));
      },
    });

    setLoaders({
      buildings: buildingsLoader,
      roads: roadsLoader,
      water: waterLoader,
    });

    let isLoading = false;
    let controller = null;

    async function updateChunks() {
      if (isLoading) return;
      isLoading = true;

      const [lon, lat] = proj4(webMercator, wgs84, [
        controls.target.x + centerX,
        controls.target.z + centerZ,
      ]);

      // Система тайлов
      const tileSize = 0.05; // размер тайла в градусах (~5.5 км на экваторе)
      const viewRadius = 2; // загружаем 5x5 сетку тайлов

      const centerTileX = Math.floor(lon / tileSize);
      const centerTileY = Math.floor(lat / tileSize);

      const tilesToLoad = [];
      const activeTiles = new Set();

      for (let dx = -viewRadius; dx <= viewRadius; dx++) {
        for (let dy = -viewRadius; dy <= viewRadius; dy++) {
          const tileX = centerTileX + dx;
          const tileY = centerTileY + dy;

          const minLon = tileX * tileSize;
          const minLat = tileY * tileSize;
          const maxLon = (tileX + 1) * tileSize;
          const maxLat = (tileY + 1) * tileSize;

          const tileKey = `${tileX}_${tileY}`;
          activeTiles.add(tileKey);

          tilesToLoad.push({ minLon, minLat, maxLon, maxLat, key: tileKey });
        }
      }

      if (controller) controller.abort();
      controller = new AbortController();

      try {
        await Promise.all(
          // ThreeScene.js - updateChunks()
          // ...
          tilesToLoad.map((tile) =>
            Promise.all([
              buildingsLoader.loadChunk(
                tile.minLon,
                tile.minLat,
                tile.maxLon,
                tile.maxLat,
                {
                  simplify: 2.0,
                  signal: controller.signal,
                  useCache: true,
                  keyHint: `buildings_${tile.key}`,
                }
              ),
              roadsLoader.loadChunk(
                tile.minLon,
                tile.minLat,
                tile.maxLon,
                tile.maxLat,
                {
                  simplify: 0.5,
                  signal: controller.signal,
                  useCache: true,
                  keyHint: `roads_${tile.key}`,
                }
              ),
            ])
          )
          // ...
        );

        for (const key of buildingsLoader.meshGroups.keys()) {
          const match = key.match(/^buildings_(-?\d+)_(-?\d+)$/);
          if (match) {
            const tileKey = `${match[1]}_${match[2]}`;
            if (!activeTiles.has(tileKey)) {
              buildingsLoader.removeChunk(key);
            }
          }
        }

        for (const key of roadsLoader.meshGroups.keys()) {
          const match = key.match(/^roads_(-?\d+)_(-?\d+)$/);
          if (match) {
            const tileKey = `${match[1]}_${match[2]}`;
            if (!activeTiles.has(tileKey)) {
              roadsLoader.removeChunk(key);
            }
          }
        }
      } catch (e) {
        if (e.name === "AbortError") {
          console.warn("[Scene] Previous fetch aborted");
        } else {
          console.error("[Scene] loadChunk error:", e);
        }
      } finally {
        isLoading = false;
      }
    }

    let updateTimeout;
    const debouncedUpdate = () => {
      clearTimeout(updateTimeout);
      updateTimeout = setTimeout(updateChunks, 250);
    };

    controls.addEventListener("change", debouncedUpdate);
    updateChunks();

    const groundGeom = new THREE.PlaneGeometry(500000, 500000, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0xf0f0f0,
      roughness: 1,
      metalness: 0,
    });
    const ground = new THREE.Mesh(groundGeom, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    ground.receiveShadow = true;
    scene.add(ground);

    let frame;
    const loop = () => {
      cube.rotation.y += 0.005;
      ground.position.x = camera.position.x;
      ground.position.z = camera.position.z;

      controls.update();
      renderer.render(scene, camera);
      frame = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frame);
      clearTimeout(updateTimeout);
      controls.removeEventListener("change", debouncedUpdate);
      window.removeEventListener("resize", handleResize);
      cleanupRaycast();
      buildingsLoader.clearAll();
      roadsLoader.clearAll();
      container.removeChild(renderer.domElement);
      renderer.dispose();
      cube.geometry.dispose();
      cube.material.dispose();
    };
  }, []);

  return (
    <div className="w-full h-full relative">
      <div ref={ref} className="w-full h-full" />
    </div>
  );
}
