import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { RENDERERS } from "./RenderersMap.js";

export class ChunkLoader {
  constructor(scene, opts = {}) {
    this.scene = scene;
    this.loaded = new Map();
    this.meshGroups = new Map();
    this.inFlight = new Map();

    this.url = opts.url || "http://127.0.0.1:8000/chunk";
    this.onProgress = opts.onProgress || (() => {});
    this.centerOffset = opts.centerOffset || [0, 0];

    // Теперь поддерживаем несколько слоёв одновременно
    this.layers = opts.layers || ["buildings", "roads", "water"];
    this.MAX_CHUNKS = opts.maxChunks || 50;

    // Создаём рендереры для каждого слоя
    this.renderers = {};
    for (const layer of this.layers) {
      const Renderer = RENDERERS[layer];
      if (Renderer) {
        this.renderers[layer] = new Renderer(this.centerOffset);
      }
    }
  }

  _chunkKey(a, b, c, d) {
    return `${a.toFixed(6)}_${b.toFixed(6)}_${c.toFixed(6)}_${d.toFixed(6)}`;
  }

  clampLatLon(lon, lat) {
    lon = Math.max(-180, Math.min(180, lon));
    lat = Math.max(-85.0511, Math.min(85.0511, lat));
    return [lon, lat];
  }

  async loadChunk(minLon, minLat, maxLon, maxLat, opts = {}) {
    const {
      simplify = 1,
      signal = null,
      useCache = true,
      keyHint = null,
      limit = 2000, // Увеличиваем лимит по умолчанию
    } = opts;

    const [minx, miny] = this.clampLatLon(minLon, minLat);
    const [maxx, maxy] = this.clampLatLon(maxLon, maxLat);
    const key = keyHint || this._chunkKey(minx, miny, maxx, maxy);

    if (useCache) {
      if (this.loaded.has(key)) return this.loaded.get(key);
      if (this.inFlight.has(key)) return this.inFlight.get(key);
    }

    // Загружаем все слои параллельно
    const fetchPromises = this.layers.map((layer) =>
      this._fetchLayer(layer, minx, miny, maxx, maxy, simplify, limit, signal)
    );

    const allPromise = Promise.all(fetchPromises)
      .then((layerDataArray) => {
        const combinedData = {
          layers: {},
          totalFeatures: 0,
        };

        layerDataArray.forEach((data, idx) => {
          const layer = this.layers[idx];
          if (data && data.features) {
            combinedData.layers[layer] = data;
            combinedData.totalFeatures += data.features.length;
          }
        });

        if (useCache) this.loaded.set(key, combinedData);

        const rendered = this._renderMultiLayer(combinedData, key);

        this.onProgress({
          key,
          featuresTotal: combinedData.totalFeatures,
          rendered,
          meshesTotal: this.meshGroups.size,
          bounds: { minx, miny, maxx, maxy },
        });

        return combinedData;
      })
      .catch((e) => {
        if (useCache) this.loaded.delete(key);
        if (e.name !== "AbortError")
          console.error("ChunkLoader fetch error:", e);
        return null;
      })
      .finally(() => {
        this.inFlight.delete(key);
      });

    if (useCache) this.inFlight.set(key, allPromise);

    return allPromise;
  }

  async _fetchLayer(layer, minx, miny, maxx, maxy, simplify, limit, signal) {
    const qs = new URLSearchParams({
      minx: String(minx),
      miny: String(miny),
      maxx: String(maxx),
      maxy: String(maxy),
      simplify: String(simplify),
      limit: String(limit),
      layer: layer,
    });
    const url = `${this.url}?${qs.toString()}`;

    try {
      const r = await fetch(url, { signal });
      if (!r.ok) throw new Error(`${layer}: server ${r.status}`);
      return await r.json();
    } catch (e) {
      if (e.name !== "AbortError") {
        console.warn(`Failed to fetch ${layer}:`, e.message);
      }
      return null;
    }
  }

  _renderMultiLayer(combinedData, key) {
    if (!combinedData || !combinedData.layers) return 0;

    if (this.meshGroups.has(key)) {
      this.removeChunk(key);
    }

    const group = new THREE.Group();
    let totalRendered = 0;

    // Рендерим каждый слой отдельно, затем объединяем
    for (const [layerName, data] of Object.entries(combinedData.layers)) {
      if (!data || !data.features) continue;

      const renderer = this.renderers[layerName];
      if (!renderer) continue;

      const geometries = [];
      const materials = new Map();

      for (const feature of data.features) {
        if (!feature.geometry) continue;
        const meshes = renderer.renderFeature(feature);
        if (!meshes) continue;

        for (const m of meshes) {
          if (!m || !m.geometry) continue;

          // Группируем геометрии по материалам для оптимизации
          const matKey = this._getMaterialKey(m.material);
          if (!materials.has(matKey)) {
            materials.set(matKey, { material: m.material, geometries: [] });
          }
          materials.get(matKey).geometries.push(m.geometry);
          totalRendered++;
        }
      }

      // Создаём меши для каждого типа материала
      for (const { material, geometries: geomsForMat } of materials.values()) {
        if (geomsForMat.length === 0) continue;

        try {
          const mergedGeometry = mergeGeometries(geomsForMat, false);
          const mesh = new THREE.Mesh(mergedGeometry, material);
          mesh.castShadow = true;
          mesh.receiveShadow = true;
          mesh.userData.layer = layerName;
          group.add(mesh);
        } catch (e) {
          console.warn(`Failed to merge geometries for ${layerName}:`, e);
          // Если мердж не удался, добавляем по отдельности
          geomsForMat.forEach((geom) => {
            const mesh = new THREE.Mesh(geom, material.clone());
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            mesh.userData.layer = layerName;
            group.add(mesh);
          });
        }
      }
    }

    if (group.children.length > 0) {
      this.scene.add(group);
      this.meshGroups.set(key, group);

      // Ограничиваем количество чанков в сцене
      if (this.meshGroups.size > this.MAX_CHUNKS) {
        const oldestKey = this.meshGroups.keys().next().value;
        this.removeChunk(oldestKey);
      }
    }

    return totalRendered;
  }

  _getMaterialKey(material) {
    return `${material.color?.getHex() || 0}_${material.roughness}_${
      material.metalness
    }_${material.transparent ? 1 : 0}`;
  }

  removeChunk(key) {
    if (!this.meshGroups.has(key)) return;
    const g = this.meshGroups.get(key);
    this.scene.remove(g);
    g.traverse((n) => {
      if (n.geometry) n.geometry.dispose();
      if (n.material) {
        if (Array.isArray(n.material)) {
          n.material.forEach((m) => m.dispose());
        } else {
          n.material.dispose();
        }
      }
    });
    this.meshGroups.delete(key);
    this.loaded.delete(key);
  }

  clearAll() {
    for (const key of this.meshGroups.keys()) this.removeChunk(key);
    this.loaded.clear();
    this.inFlight.clear();
  }
}
